INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(7501, '1 Samuel 31:1', '1 Samuel', 31, 1, '&nbsp;فلستيانو د جِلبوعه په غرۀ د بنى اِسرائيلو خِلاف جنګ وکړو. د بنى اِسرائيلو فوجيان د فلستيانو نه وتښتېدل او د بنى اِسرائيلو ډېر کسان مړۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7502, '1 Samuel 31:2', '1 Samuel', 31, 2, '&nbsp;خو فلستيان ساؤل ته نزدې ورورسېدل او د ساؤل درې زامن يې ووژل، يونتن، ابينداب او مُلکى‌شوَع.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7503, '1 Samuel 31:3', '1 Samuel', 31, 3, '&nbsp;د ساؤل نه ګېرچاپېره جنګ ډېر سخت وو او هغه په خپله د دشمن په غشو باندې لګېدلے وو او سخت زخمى وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7504, '1 Samuel 31:4', '1 Samuel', 31, 4, '&nbsp;هغۀ وسله وړُونکى زلمى ته ووئيل، ”خپله تُوره راوباسه او ما ووژنه، چې دا ناسنته فلستيان ما په تُوره ونۀ وهى او په عذاب مې نۀ کړى.“ خو هغه زلمے د داسې کولو په وجه سخت يرېدو. نو ساؤل خپله تُوره واخستله او خپل ځان يې پرې وروغورزولو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7505, '1 Samuel 31:5', '1 Samuel', 31, 5, '&nbsp;هغه زلمى ته پته ولګېده چې ساؤل مړ شو، نو هغۀ خپل ځان په خپله تُوره وروغورزولو او د ساؤل په څنګ کښې مړ شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7506, '1 Samuel 31:6', '1 Samuel', 31, 6, '&nbsp;نو داسې ساؤل، د هغۀ درې زامن او هغه زلمے مړ شو، په هغه ورځ باندې د ساؤل ټول سړى مړۀ شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7507, '1 Samuel 31:7', '1 Samuel', 31, 7, '&nbsp;کله چې د يزرعيل او د اُردن د سيند نمرخاتۀ بل طرف ته بنى اِسرائيليان خبر شول چې د بنى اِسرائيلو لښکر تښتېدلے دے او ساؤل او د هغۀ زامن وژلے شوى دى، نو هغوئ خپل ښارونه پرېښودل او وتښتېدل. نو فلستيان راغلل او دا ښارونه يې ونيول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7508, '1 Samuel 31:8', '1 Samuel', 31, 8, '&nbsp;په ورپسې ورځ باندې فلستيان د لاشونو لوټ کولو دپاره لاړل او هغوئ د ساؤل او د هغۀ د درېو زامنو لاشونه وليدل چې د جِلبوعه په غرۀ باندې پراتۀ وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7509, '1 Samuel 31:9', '1 Samuel', 31, 9, '&nbsp;هغوئ د ساؤل سر پرې کړو او زغره يې ترې نه لرې کړه او ټول فلستيان ته يې پېغام وړُونکى ولېږل چې خپلو بُت‌خانو او د هغوئ خلقو ته دا زېرے ورسوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7510, '1 Samuel 31:10', '1 Samuel', 31, 10, '&nbsp;بيا هغوئ د هغۀ وسلې د عستارات په بُت‌خانه واچولې او هغوئ د هغۀ لاش د بيت‌شان ښار په دېوال پورې په مېخونو ټک وهلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7511, '1 Samuel 31:11', '1 Samuel', 31, 11, '&nbsp;کله چې په جِلعاد کښې د يبيس خلق خبر شول چې فلستيانو د ساؤل سره څۀ کړى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7512, '1 Samuel 31:12', '1 Samuel', 31, 12, '&nbsp;نو ښۀ بهادر سړى ووتل او ټوله شپه يې بيت‌شان ته مزل وکړو. هغوئ د ساؤل او د هغۀ د زامنو لاشونه د ښار دېوال نه راکوز کړل او واپس يې يبيس ته يوړل او هلته يې وسوزول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7513, '1 Samuel 31:13', '1 Samuel', 31, 13, '&nbsp;بيا هغوئ هډُوکى يوړل او په ښار کښې يې د غز د ونې لاندې ښخ کړل او اووۀ ورځې هغوئ روژه ونيوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7514, '2 Samuel 1:1', '2 Samuel', 1, 1, '&nbsp;د ساؤل د مرګ نه پس چې داؤد په عماليقيانو فتح وموندله نو راغلو او دوه ورځې په صِقلاج کښې ايسار شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7515, '2 Samuel 1:2', '2 Samuel', 1, 2, '&nbsp;په درېمه ورځ د ساؤل د کېمپ نه يو زلمے راورسېدو. د دې دپاره چې خپل غم څرګند کړى، هغۀ خپلې جامې شلولې وې او په سر يې خاورې اچولې وې. کله چې هغه داؤد له راغلو نو د عزت نه ټيټ شو او پړمخې په زمکه پرېوتو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7516, '2 Samuel 1:3', '2 Samuel', 1, 3, '&nbsp;داؤد ترې نه تپوس وکړو، ”تۀ د کوم ځائ نه راغلے يې؟“ هغۀ ورته ووئيل، ”زۀ د بنى اِسرائيلو د کېمپ نه راتښتېدلے يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7517, '2 Samuel 1:4', '2 Samuel', 1, 4, '&nbsp;داؤد ورته وفرمائيل، ”ما ته ووايه چې څۀ شوى دى.“ هغۀ جواب ورکړو، ”زمونږ فوجيان د جنګ نه راتښتېدلى دى او زمونږ ډېر سړى وژلے شوى دى. ساؤل او د هغۀ زوئ يونتن هم وژلے شوى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7518, '2 Samuel 1:5', '2 Samuel', 1, 5, '&nbsp;داؤد ترې نه تپوس وکړو، ”تا ته څۀ پته ده چې ساؤل او يونتن مړۀ شوى دى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7519, '2 Samuel 1:6', '2 Samuel', 1, 6, '&nbsp;هغۀ جواب ورکړو، ”د جِلبوعه په غرۀ باندې داسې وشول او ما وليدل چې ساؤل په خپله نېزه باندې تکيه لګولې وه او د دشمن جنګى ګاډۍ او په آسونو سوارۀ فوجيان ورنزدې کېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7520, '2 Samuel 1:7', '2 Samuel', 1, 7, '&nbsp;بيا هغه راوګرځېدو او زۀ يې وليدم او را وې غوښتم. ما ورته ووئيل چې زۀ حاضر يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7521, '2 Samuel 1:8', '2 Samuel', 1, 8, '&nbsp;هغۀ زما نه تپوس وکړو چې تۀ څوک يې، نو ما ورته ووئيل چې زۀ د عماليقى قبيلې يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7522, '2 Samuel 1:9', '2 Samuel', 1, 9, '&nbsp;بيا هغۀ ووئيل چې دلته راشه او ما ووژنه. ځکه چې زما ځنکدن دے خو زۀ تر اوسه پورې ژوندے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7523, '2 Samuel 1:10', '2 Samuel', 1, 10, '&nbsp;نو زۀ هغۀ له ورغلم او ومې وژلو، ځکه چې ما ته پته وه چې څنګه وغورزيږى نو هغه به مړ شى. بيا ما د هغۀ د سر نه تاج او د هغۀ د لاس نه بنګړے واخستلو او صاحِبه، تا له مې راوړل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7524, '2 Samuel 1:11', '2 Samuel', 1, 11, '&nbsp;داؤد د غم نه خپلې جامې وشلولې او د هغۀ ټولو سړو هم دغه شان وکړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7525, '2 Samuel 1:12', '2 Samuel', 1, 12, '&nbsp;هغوئ په غم غمژن شول او تر ماښامه پورې يې د ساؤل، يونتن او بنى اِسرائيلو دپاره روژه ونيوله کوم چې د مالِک خُدائ د لښکر خلق وُو، ځکه چې دا خلق په جنګ کښې مړۀ شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7526, '2 Samuel 1:13', '2 Samuel', 1, 13, '&nbsp;داؤد د هغه زلمى نه تپوس وکړو کوم چې هغۀ له دا خبر راوړے وو چې، ”تۀ د کوم ځائ يې؟“ هغۀ ورته ووئيل، ”زۀ يو عماليقے مسافر يم، خو زۀ ستا په مُلک کښې اوسېږم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7527, '2 Samuel 1:14', '2 Samuel', 1, 14, '&nbsp;داؤد ترې نه تپوس وکړو، ”تا دا جرأت څنګه وکړو چې د مالِک خُدائ خوښ کړے شوے بادشاه دې ووژلو؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7528, '2 Samuel 1:15', '2 Samuel', 1, 15, '&nbsp;بيا داؤد خپل يو سړے راوغوښتلو او ورته يې ووئيل، ”هغه ووژنه.“ نو هغه سړى عماليقے ووهلو او هغه په ټکى مړ شو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7529, '2 Samuel 1:16', '2 Samuel', 1, 16, '&nbsp;او داؤد هغه عماليقى ته وفرمائيل، ”خُون دې د خپلې غاړې دے. تا په خپله د ځان سره دا بد وکړل چې تا دا خبره وکړه چې تا د مالِک خُدائ خوښ کړے شوے بادشاه ووژلو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7530, '2 Samuel 1:17', '2 Samuel', 1, 17, '&nbsp;داؤد د ساؤل او د هغۀ زوئ يونتن دپاره دا د غم سندره ووئيله،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7531, '2 Samuel 1:18', '2 Samuel', 1, 18, '&nbsp;او حُکم يې وکړو چې دا د يهوداه خلقو ته وښودلے شى. هغۀ په دې باندې د ليندې سندرې نوم کېښودو، دا د ياشر په کِتاب کښې ليکلے شوې ده:', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7532, '2 Samuel 1:19', '2 Samuel', 1, 19, '&nbsp;”په غرونو باندې د بنى اِسرائيلو عزتمند خلق مړۀ شوى دى. زمونږ تکړه فوجيان غورزېدلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7533, '2 Samuel 1:20', '2 Samuel', 1, 20, '&nbsp;په جات کښې دا اِعلان مۀ کوه او د اسقلون په کوڅو کښې هم دا اِعلان مۀ کوه. د فلستيانو ښځې مۀ خوشحالوه، د غېرو قومونو لوڼه مۀ خوشحالوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7534, '2 Samuel 1:21', '2 Samuel', 1, 21, '&nbsp;د جِلبوعه په غرونو باندې دې پرخه او باران نۀ وريږى، د دې ځائ پټى دې همېشه شنډ وى. ځکه چې د تکړه کسانو ډالونه هلته په بې‌عزتۍ کښې پراتۀ دى، د ساؤل ډال دې نور د تېلو سره نۀ شى ځلولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7535, '2 Samuel 1:22', '2 Samuel', 1, 22, '&nbsp;د يونتن لينده د مرګ وه، د ساؤل تُوره بې‌رحمه وه، طاقتور يې غورزول او دشمن يې وژلو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7536, '2 Samuel 1:23', '2 Samuel', 1, 23, '&nbsp;ساؤل او يونتن ډېر ښۀ او خواږۀ وُو، په ژوند کښې هم يو ځائ او په مرګ کښې هم يو ځائ، د باز نه تېز وُو او د زمرو نه تکړه وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7537, '2 Samuel 1:24', '2 Samuel', 1, 24, '&nbsp;د بنى اِسرائيل ښځې د ساؤل دپاره د غم ژړا کوى. هغۀ تا ته سرې ښې جامې درواغوستلې او په کالو او سرو زرو يې ښائسته کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7538, '2 Samuel 1:25', '2 Samuel', 1, 25, '&nbsp;تکړه فوجيان غورزېدلى دى، هغوئ په جنګ کښې وژلے شوى دى. يونتن په غرونو کښې مړ پروت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7539, '2 Samuel 1:26', '2 Samuel', 1, 26, '&nbsp;زما وروره يونتنه، زۀ ستا په غم غمژن يم، تۀ په ما باندې څومره ګران وې. ستا مينه زما دپاره څومره ښۀ وه، د ښځو د مينې نه هم ښۀ وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7540, '2 Samuel 1:27', '2 Samuel', 1, 27, '&nbsp;تکړه فوجيان غورزېدلى دى، د هغوئ وسلې تباه شوې دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7541, '2 Samuel 2:1', '2 Samuel', 2, 1, '&nbsp;د دې نه پس، داؤد د مالِک خُدائ نه تپوس وکړو، ”زۀ لاړ شم څۀ چې د يهوداه يو ښار قبضه کړم؟“ مالِک خُدائ ورته وفرمائيل، ”آو، لاړ شه.“ داؤد ترې نه تپوس وکړو، ”کوم يو قبضه کړم؟“ مالِک خُدائ ورته وفرمائيل، ”حبرون.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7542, '2 Samuel 2:2', '2 Samuel', 2, 2, '&nbsp;نو داؤد حبرون ته لاړو، خپلې دوه ښځې يې هم د ځان سره بوتلې، اخينوعم چې د يزرعيل وه او ابى‌جيل چې د نابال کونډه وه، چې هغه د کرمل وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7543, '2 Samuel 2:3', '2 Samuel', 2, 3, '&nbsp;هغۀ خپل سړى او د هغوئ خاندان هم د ځان سره بوتلل او د حبرون نه ګېرچاپېره په ښارونو کښې دېره شول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7544, '2 Samuel 2:4', '2 Samuel', 2, 4, '&nbsp;بيا د يهوداه سړى حبرون ته راغلل او داؤد يې د يهوداه د بادشاه په توګه مقرر کړو. کله چې داؤد خبر شو چې په جِلعاد کښې د يبيس خلقو ساؤل ښخ کړے دے،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7545, '2 Samuel 2:5', '2 Samuel', 2, 5, '&nbsp;هغۀ هلته يو څو سړى د دې پېغام سره ولېږل، ”مالِک خُدائ دې تا له برکت درکړى ځکه چې تا خپل بادشاه ته وفادارى ښودلې ده چې هغه دې ښخ کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7546, '2 Samuel 2:6', '2 Samuel', 2, 6, '&nbsp;نو مالِک خُدائ دې په تا مِهربانه شى او تا ته دې خپله وفادارى وښائى. تا چې څۀ کړى دى نو د هغې په وجه به زۀ هم تا سره ښۀ سلوک وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7547, '2 Samuel 2:7', '2 Samuel', 2, 7, '&nbsp;تکړه او بهادر شه. ستاسو بادشاه ساؤل مړ دے او د يهوداه خلقو زۀ د بادشاه په توګه مقرر کړے يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7548, '2 Samuel 2:8', '2 Samuel', 2, 8, '&nbsp;خو د ساؤل د لښکر مشر د نير زوئ ابنير د ساؤل د زوئ اشبوست سره تښتېدلے وو او محنايم ته د اُردن نه پورې وتے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7549, '2 Samuel 2:9', '2 Samuel', 2, 9, '&nbsp;هلته ابنير اشبوست د دې علاقو بادشاه جوړ کړو يعنې د جِلعاد، آشر، يزرعيل، اِفرائيم او بنيامين او په حقيقت کښې د ټول اِسرائيل بادشاه يې جوړ کړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7550, '2 Samuel 2:10', '2 Samuel', 2, 10, '&nbsp;هغه د څلوېښتو کالو وو چې هغه د اِسرائيل بادشاه جوړ شو او دوه کاله يې بادشاهى وکړه. خو د يهوداه قبيلې خلق د داؤد وفادار وُو،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7551, '2 Samuel 2:11', '2 Samuel', 2, 11, '&nbsp;او هغۀ په يهوداه باندې په حبرون کښې اووۀ کاله او شپږ مياشتې بادشاهى وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7552, '2 Samuel 2:12', '2 Samuel', 2, 12, '&nbsp;ابنير او د اشبوست آفسران د محنايم نه د جبعون ښار ته لاړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7553, '2 Samuel 2:13', '2 Samuel', 2, 13, '&nbsp;يوآب چې د هغۀ مور ضروياه وه او د داؤد نور آفسران د هغوئ سره د ډنډ سره مِلاو شول، چرته چې هغوئ ټول کښېناستل، يوه ډله د ډنډ په يو طرف او بله ډله د ډنډ په بل طرف ناسته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7554, '2 Samuel 2:14', '2 Samuel', 2, 14, '&nbsp;ابنير يوآب ته ووئيل، ”راځئ چې د دواړو طرفونو نه يو څو زلمى واخلو چې دوئ په خپلو کښې زمونږ په وړاندې لاس په لاس جنګ وکړى.“ يوآب ورته ووئيل، ”بلکل ټيک ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7555, '2 Samuel 2:15', '2 Samuel', 2, 15, '&nbsp;نو دولسو سړو چې کومو د اشبوست او د بنيامين د قبيلې نمائندګى کوله، د داؤد دولسو سړو سره لاس په لاس جنګ وکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7556, '2 Samuel 2:16', '2 Samuel', 2, 16, '&nbsp;هر يو سړى خپل مخالف د سر وېښتو نه ونيولو او په خپل مخالف سړى کښې يې تُوره دننه کړه، نو داسې څليريشت واړه په يو ځائ وغورزېدل او مړۀ شول. نو په جبعون کښې هغه ځائ د ”د تُورو مېدان“ په نوم ياديږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7557, '2 Samuel 2:17', '2 Samuel', 2, 17, '&nbsp;بيا سخت جنګ شروع شو او ابنير او بنى اِسرائيلو د داؤد د سړو نه شکست وخوړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7558, '2 Samuel 2:18', '2 Samuel', 2, 18, '&nbsp;د ضروياه درې زامن هلته وُو، يوآب، ابيشے او عساهيل. عساهيل د ځنګلى هوسۍ په شان تېزه منډه وهلے شوه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7559, '2 Samuel 2:19', '2 Samuel', 2, 19, '&nbsp;هغه په ابنير پسې روان شو او سيدها يې په هغۀ پسې منډې وهلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7560, '2 Samuel 2:20', '2 Samuel', 2, 20, '&nbsp;ابنير چې په شا وکتل نو وې وئيل، ”عساهيله، دا تۀ يې؟“ هغۀ جواب ورکړو، ”آو، دا زۀ يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7561, '2 Samuel 2:21', '2 Samuel', 2, 21, '&nbsp;ابنير ورته ووئيل، ”ما پسې مۀ راځه. په يو بل فوجى پسې منډه کړه او چې د هغۀ سره څۀ وى هغه ترې نه واخله.“ خو عساهيل ورپسې روان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7562, '2 Samuel 2:22', '2 Samuel', 2, 22, '&nbsp;ابنير يو ځل بيا هغۀ ته ووئيل، ”ما پسې مۀ راځه. تۀ ما دې ته ولې مجبوروې چې ودې وژنم؟ زۀ به ستا ورور يوآب ته څنګه مخامخ کېږم؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7563, '2 Samuel 2:23', '2 Samuel', 2, 23, '&nbsp;خو عساهيل نۀ منع کېدو، نو ابنير د خپلې نېزې د بېخ سره هغه په خېټه داسې ووهلو چې نېزه د هغۀ نه شاته ووتله. عساهيل په زمکه وغورزېدو او په ټکى مړ شو او چې هر څوک هغه ځائ ته راتلل چې چرته هغه پروت وو نو هلته ايسارېدل او ودرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7564, '2 Samuel 2:24', '2 Samuel', 2, 24, '&nbsp;خو يوآب او ابيشے په ابنير پسې روان شول او نمرپرېواتو په وخت هغوئ د امه غرۀ ته ورسېدل، کوم چې د جبعون صحرا په لاره د جياح نمرخاتۀ طرف ته دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7565, '2 Samuel 2:25', '2 Samuel', 2, 25, '&nbsp;د بنيامين د قبيلې خلق يو ځل بيا د ابنير نه راتاو شول او د يو غرۀ په سر باندې ودرېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7566, '2 Samuel 2:26', '2 Samuel', 2, 26, '&nbsp;ابنير يوآب راوغوښتو او ورته يې ووئيل، ”مونږ به د تل دپاره جنګ کوُو څۀ؟ تا ته پته نۀ لګى څۀ چې د دې اَنجام به ډېر خراب وى؟ مونږ ستاسو اِسرائيلى وروڼه يُو. خو هغه وخت به کله وى چې تۀ خپلو سړو له حُکم ورکړې چې په مونږ پسې نۀ راځى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7567, '2 Samuel 2:27', '2 Samuel', 2, 27, '&nbsp;يوآب ورته ووئيل، ”زۀ په ژوندى خُدائ پاک قسم خورم، کۀ تا خبرې نۀ وے کړې نو زما سړى به تر سبا سحره پورې په تا پسې درتللے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7568, '2 Samuel 2:28', '2 Samuel', 2, 28, '&nbsp;بيا يوآب خپلو سړو ته بيګل د نښې په توګه وغږولو چې هغوئ نور په بنى اِسرائيلو پسې نۀ ځى، نو داسې جنګ بس شو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7569, '2 Samuel 2:29', '2 Samuel', 2, 29, '&nbsp;ابنير او د هغۀ سړو په هغه ټوله شپه د اُردن په مېدان کښې مزل وکړو، هغوئ د اُردن سيند نه پورې وتل او په ورپسې ټول سحر مزل کولو نه پس، هغوئ واپس محنايم ته ورسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7570, '2 Samuel 2:30', '2 Samuel', 2, 30, '&nbsp;کله چې يوآب په هغوئ پسې نور نۀ تلو، هغۀ خپل ټول سړى راغونډ کړل او پته ورته ولګېده چې د عساهيل نه علاوه، نولس کسان غېب وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7571, '2 Samuel 2:31', '2 Samuel', 2, 31, '&nbsp;خو د داؤد سړو د بنيامين قبيلې د ابنير درې سوه شپېتۀ سړى وژلى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7572, '2 Samuel 2:32', '2 Samuel', 2, 32, '&nbsp;يوآب او د هغۀ سړو د عساهيل لاش واخستلو او په بيت‌لحم کښې د خپل خاندان په قبر کښې يې ښخ کړو. بيا هغوئ ټوله شپه مزل وکړو او سحر وختى حبرون ته واپس ورسېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7573, '2 Samuel 3:1', '2 Samuel', 3, 1, '&nbsp;کومو فوجيانو چې د ساؤل د خاندان ملګرتيا کوله او چا چې د داؤد ملګرتيا کوله د هغوئ په مينځ کښې تر ډېرې مودې پورې جنګ جارى وو. داؤد چې څومره زيات تکړه کېدو نو مخالفين يې دومره کمزورى کېدل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7574, '2 Samuel 3:2', '2 Samuel', 3, 2, '&nbsp;په حبرون کښې د داؤد دا زامن پېدا شول: د هغۀ مشر زوئ امنون وو، چې د هغۀ مور د يزرعيل اخينوعم وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7575, '2 Samuel 3:3', '2 Samuel', 3, 3, '&nbsp;د هغۀ دوېم زوئ کِلياب وو، د هغۀ مور ابى‌جيل د کرمل د نابال کونډه وه، درېم زوئ يې ابى‌سلوم وو، د هغۀ مور معکه د جسور بادشاه تلمى لور وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7576, '2 Samuel 3:4', '2 Samuel', 3, 4, '&nbsp;څلورم ادونياه وو چې د هغۀ مور حجيت وه، پينځم سفطياه وو، چې د هغۀ مور ابيطال وه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7577, '2 Samuel 3:5', '2 Samuel', 3, 5, '&nbsp;شپږم زوئ يې اِترعام وو چې د هغۀ مور عِجلاه وه. د هغۀ دا ټول زامن په حبرون کښې پېدا شوى وُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7578, '2 Samuel 3:6', '2 Samuel', 3, 6, '&nbsp;کله چې د داؤد د فوجيانو او د هغه فوجيانو په مينځ کښې جنګ جارى وو کومو چې د ساؤل د خاندان ملګرتيا کوله، نو ابنير د ساؤل ملګرو کښې نور هم زيات تکړه کېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7579, '2 Samuel 3:7', '2 Samuel', 3, 7, '&nbsp;يوه ورځ د ساؤل زوئ اشبوست په ابنير اِلزام ولګولو چې تۀ د ساؤل د وينځې د آيه د لور رِصفخ سره څملې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7580, '2 Samuel 3:8', '2 Samuel', 3, 8, '&nbsp;په دې باندې ابنير سخت غصه شو. هغۀ ووئيل، ”ستا خيال دا دے څۀ چې زۀ به د ساؤل سره بې‌وفائى وکړم؟ ستا خيال دا دے چې زۀ د يهوداه سپے يم؟ زۀ د شروع نه ستا د پلار ساؤل، د هغۀ وروڼو او د هغۀ د دوستانو وفادار يم او ما تۀ د داؤد د شکست نه بچ کړے يې، خو نن تۀ په ما کښې د يوې ښځې په حقله غلطى لټوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7581, '2 Samuel 3:11', '2 Samuel', 3, 11, '&nbsp;اشبوست د ابنير نه سخت يرېدو او يوه خبره يې هم نۀ شوه کولے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7582, '2 Samuel 3:12', '2 Samuel', 3, 12, '&nbsp;ابنير داؤد له پېغام وړُونکى ورولېږل، چې هغه په هغه وخت کښې په حبرون کښې وو، چې داسې ورته ووائى، ”په دې مُلک به څوک بادشاهى کوى؟ زما سره يو تړون وکړه او زۀ به ستا مدد وکړم چې ټول بنى اِسرائيليان په بادشاه جوړېدو کښې ستا ملګرتيا وکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7583, '2 Samuel 3:13', '2 Samuel', 3, 13, '&nbsp;داؤد ورته وفرمائيل، ”ټيک ده. زۀ به تا سره په يو شرط باندې تړون وکړم. کله چې تۀ ما سره مِلاوېدو له راځې نو تۀ به ما له خامخا د ساؤل لور ميکل راولې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7584, '2 Samuel 3:14', '2 Samuel', 3, 14, '&nbsp;او داؤد اشبوست له هم پېغام وړُونکى ولېږل چې ورته ووائى، ”ما له خپله ښځه ميکل واپس راکړه. ما د هغې د ودېدو دپاره سل فلستيان وژلى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7585, '2 Samuel 3:15', '2 Samuel', 3, 15, '&nbsp;نو اشبوست هغه د خپل خاوند د ليس زوئ فلطى‌ايل نه بوتله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7586, '2 Samuel 3:16', '2 Samuel', 3, 16, '&nbsp;فلطى‌ايل په هغې پسې د بحوريم ښار پورې روان وو او ژړل يې. خو چې کله ورته ابنير ووئيل چې، ”واپس کور ته لاړ شه،“ نو هغه لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7587, '2 Samuel 3:17', '2 Samuel', 3, 17, '&nbsp;ابنير د بنى اِسرائيلو مشرانو له لاړو او ورته يې ووئيل، ”د ډېر وخت نه تاسو غوښتل چې داؤد ستاسو بادشاه شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7588, '2 Samuel 3:18', '2 Samuel', 3, 18, '&nbsp;نو اوس تاسو سره دا موقع شته. ياد ساتئ چې مالِک خُدائ فرمائيلى دى، زۀ به د خپل خِدمت کوونکى داؤد نه کار واخلم چې زما خلق بنى اِسرائيليان د فلستيانو نه او د هغوئ د ټولو دشمنانو نه بچ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7589, '2 Samuel 3:19', '2 Samuel', 3, 19, '&nbsp;ابنير د بنيامين قبيلې خلقو ته هم ووئيل او بيا حبرون ته لاړو چې داؤد ته ووائى چې د بنيامين قبيله او بنى اِسرائيل داسې کولو ته راضى شوى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7590, '2 Samuel 3:20', '2 Samuel', 3, 20, '&nbsp;کله چې ابنير په حبرون کښې داؤد له د شلو سړو سره راغلو، نو داؤد هغوئ له يوه مېلمستيا وکړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7591, '2 Samuel 3:21', '2 Samuel', 3, 21, '&nbsp;ابنير داؤد ته ووئيل، ”ما پرېږده چې اوس زۀ لاړ شم او ټول بنى اِسرائيليان زما نېک يعنې بادشاه له راغونډ کړم چې تا سره تړون وکړى. هغوئ به تا بادشاه ومنى، نو بيا به تا ته هغه څۀ مِلاو شى چې تا څۀ غوښتل او په ټول مُلک به بادشاهى کوې.“ نو داؤد ابنير پرېښودو او هغه په خېر سره لاړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7592, '2 Samuel 3:22', '2 Samuel', 3, 22, '&nbsp;وروستو يوآب او د داؤد نور آفسران د يو حملې کولو نه راغلل او د ځان سره يې ښۀ ډېر مالِ غنيمت راوړو. ابنير د داؤد سره هلته په حبرون کښې نۀ وو، ځکه چې داؤد هغه په خېر سره لېږلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7593, '2 Samuel 3:23', '2 Samuel', 3, 23, '&nbsp;کله چې يوآب او د هغۀ سړى راورسېدل، نو هغه خبر شو چې ابنير داؤد بادشاه له راغلے وو او په خېر سره لېږلے شوے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7594, '2 Samuel 3:24', '2 Samuel', 3, 24, '&nbsp;نو يوآب بادشاه له لاړو او هغۀ ته يې ووئيل، ”دا تا څۀ کړى دى؟ ابنير تا له راغلے وو، نو تا هغه داسې ولې پرېښودو؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7595, '2 Samuel 3:25', '2 Samuel', 3, 25, '&nbsp;هغه دلته ستا دوکه کولو دپاره راغلے وو او چې دا پته ولګوى چې تۀ څۀ څۀ کوې او چرته ځې. په حقيقت کښې تا ته دا پته ده.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7596, '2 Samuel 3:26', '2 Samuel', 3, 26, '&nbsp;د داؤد د تلو نه پس، يوآب پېغام وړُونکى ولېږل چې ابنير راولى او هغوئ هغه د سيره د کوهى نه راوستلو، خو داؤد د دې نه بېخى خبر نۀ وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7597, '2 Samuel 3:27', '2 Samuel', 3, 27, '&nbsp;کله چې ابنير حبرون ته ورسېدو، نو يوآب هغه د دروازې سره يو طرف ته بوتلو، داسې معلومېده لکه چې يوآب د هغۀ سره څۀ پټه خبره کوى او هلته يې هغه په خېټه باندې ووهلو. نو داسې ابنير ووژلے شو ځکه چې هغۀ د يوآب ورور عساهيل وژلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7598, '2 Samuel 3:28', '2 Samuel', 3, 28, '&nbsp;کله چې داؤد دا خبر واورېدو، نو هغۀ وفرمائيل، ”مالِک خُدائ ته زما او زما د خلقو پته ده چې د ابنير د ووژلو په وجه بېخى بې‌ګناه يُو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7599, '2 Samuel 3:29', '2 Samuel', 3, 29, '&nbsp;د دې سزا دې په يوآب او د هغۀ په مکمل خاندان راشى. د هغۀ د خاندان په هر نسل کښې دې داسې سړى وى چې د هغوئ د ذکر نه منى ځى يا جذامى وى يا ښځونک، يا په جنګ کښې مړۀ شى يا د هغوئ سره د خوراک کمے وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(7600, '2 Samuel 3:30', '2 Samuel', 3, 30, '&nbsp;نو داسې يوآب او د هغۀ ورور ابيشى د ابنير نه بدل واخستلو ځکه چې هغۀ د جبعون په جنګ کښې عساهيل د هغوئ ورور وژلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');